import{at as e,it as t,n,vt as r}from"./chunks/framework.CinQa4et.js";var i=JSON.parse(`{"title":"取得・送信されるデータ","description":"","frontmatter":{},"headers":[],"relativePath":"integration/data.md","filePath":"integration/data.md","lastUpdated":1793464466000}`),a={name:`integration/data.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="取得・送信されるデータ" tabindex="-1">取得・送信されるデータ <a class="header-anchor" href="#取得・送信されるデータ" aria-label="Permalink to “取得・送信されるデータ”">​</a></h1><h2 id="自動で観測するもの" tabindex="-1">自動で観測するもの <a class="header-anchor" href="#自動で観測するもの" aria-label="Permalink to “自動で観測するもの”">​</a></h2><ul><li>閲覧したページの順序。</li><li>ページが表示されている時間。背景タブ等の時間を除きます。</li><li>ページの名称、説明、種類、テーマ等。</li></ul><p>JSON-LDを優先し、見つからない項目はOGP、meta、titleへフォールバックします。JSON-LD内の参照を解決するために外部URLを勝手に取得しません。</p><p>URLのクエリとフラグメントは閲覧データから除き、パスを使います。パス自体に個人情報が入るサイトでは、除外経路の設計が必要です。</p><h2 id="ブラウザ内に保存するもの" tabindex="-1">ブラウザ内に保存するもの <a class="header-anchor" href="#ブラウザ内に保存するもの" aria-label="Permalink to “ブラウザ内に保存するもの”">​</a></h2><p>sessionStorageへ閲覧履歴、許可されたイベント・状態、表示済み・閉じた状態を保存します。別タブや別端末を1人の訪問者として結び付けません。有効期限や再検証により、古い状態をそのまま使い続けない設計です。</p><p>表示上限は全端末での恒久的な回数制限ではありません。ブラウザ内の有効な履歴に対する制限です。</p><h2 id="判断時に自前apiへ送るもの" tabindex="-1">判断時に自前APIへ送るもの <a class="header-anchor" href="#判断時に自前apiへ送るもの" aria-label="Permalink to “判断時に自前APIへ送るもの”">​</a></h2><p>必要なページ情報と表示時間、登録済みの行動・状態、配信制約の判断に使う表示済み状態を送ります。送信は判断のタイミングだけです。</p><p>APIは許可/除外経路、有効な閲覧時間・件数、登録済みイベント名・状態名を検証します。SDKから送られたものをすべて無条件にJevへ渡しません。</p><h2 id="jevへ送るもの" tabindex="-1">Jevへ送るもの <a class="header-anchor" href="#jevへ送るもの" aria-label="Permalink to “Jevへ送るもの”">​</a></h2><p>有効な閲覧情報から作ったstateと、施策のquestionsを送ります。生の表示時間をブラウザ内とAPIで扱い、どの閲覧を判断材料にするかはAPI側のアルゴリズムで調整します。</p><p>確定条件・AND/OR・最終的な表示はコードが扱います。質問同士で他の回答を参照させません。</p><h2 id="そのまま送らないもの" tabindex="-1">そのまま送らないもの <a class="header-anchor" href="#そのまま送らないもの" aria-label="Permalink to “そのまま送らないもの”">​</a></h2><p>フォーム入力、ページ全文、JSON-LD全体、SDKで自動取得した氏名・メール等の個人情報を送る仕組みではありません。基本メタデータにも個人情報が含まれる場合があるので、実サイトの情報と範囲を確認してください。</p><h2 id="サーバーの保存" tabindex="-1">サーバーの保存 <a class="header-anchor" href="#サーバーの保存" aria-label="Permalink to “サーバーの保存”">​</a></h2><p>閲覧者ID、閲覧者セッション、行動履歴DBは持ちません。管理者のユーザー・パスキー公開鍵・管理セッション・サイト所属・施策は、別の管理用DBへ保存します。</p><p>Jevへの送信、CDNやプロキシのログ、Cloudflare Accessの認証ログまで存在しないという意味ではありません。外部サービスの保持条件・契約・設定も運用者が確認します。</p><p>診断パネルの情報も扱いに注意し、<a href="./../operations/security">秘密情報と運用</a>を併せて確認してください。</p>`,20)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};